// Extension is explicit so plain Node (scripts/validate-i18n-city.mjs) can import
// this module and render the real strings. Metro resolves both forms. No cycle:
// regions.js imports nothing.
import { REGION_LABEL_KEY } from './regions.js'
export const LANG_CODES = {
  'English': 'en', 'Turkish': 'tr', 'Arabic': 'ar',
  'Russian': 'ru', 'Greek': 'el', 'French': 'fr',
  'Spanish': 'es', 'German': 'de', 'Persian': 'fa',
}

// The picker list, in NATIVE names — the whole point of a language control is that it is
// readable by somebody who cannot read the current language, so 'Türkçe' and never
// 'Turkish'. Order matches LANG_CODES.
//
// It lives here because there were already THREE copies of this array (App.js,
// WelcomeScreen, AuthScreen) before the wizard needed a fourth, and they had already
// drifted in shape. A language the app supports but one copy has never heard of is a
// user stuck in a language they cannot read — which is exactly the failure the wizard's
// pill exists to fix.
