    // Slice 2 — country-specific content
    petsStep3BodyEU: 'Rabies antibody titer test at an EU-approved laboratory. Result must be ≥0.5 IU/ml. If your EU Pet Passport already has a valid titer result on record, it may be accepted — verify with the TRNC Veterinary Department.',
    petsStep6BodyEU: 'Your vet must complete an official EU animal health certificate (Annex IV format). This replaces the UK-format health certificate.',
    petsEUNote: 'If your pet has a current EU Pet Passport with an up-to-date rabies vaccination and titer result, bring it — it may simplify the documentation process.',
    petsTrStep3Title: 'Turkish Veterinary Health Certificate',
    petsTrStep3Body: 'Obtain a veterinary health certificate from a government-authorised vet in Turkey before travel.',
    petsTrStep5Body: 'Obtain a Turkish export health certificate from your vet within 10 days of travel.',
    petsTurkiyeNote1: 'Titer test requirements for pets entering from Turkey may differ from other countries. Contact the TRNC Veterinary Department directly to confirm current requirements before booking.',
    petsTurkiyeNote2: 'All flights from Turkey arrive via Ercan Airport — standard import procedures and customs inspection apply on arrival.',
    petsOtherNote: 'Requirements shown are the minimum standard track. Your country of origin may have additional or different requirements. Contact the TRNC Veterinary Department with your specific country of origin before travel.',
    petsOtherStep6Body: 'Obtain an official export health certificate from your government-accredited vet within 10 days of travel. The exact format required may vary — verify with the TRNC Veterinary Department.',
