    petsTravelWarningsTitle: 'Important Warnings',
    petsPegasusTitle: 'Pegasus Airlines',
    petsCabinTitle: 'In-cabin',
    petsHoldTitle: 'Hold (cargo)',
    petsPegasusCabinBody: 'Small pets only. Maximum combined weight (pet + carrier): 8 kg. Carrier must fit under the seat. Spaces are limited — book in advance and notify the airline at time of booking.',
    petsPegasusHoldBody: 'Larger pets travel in the hold in an airline-approved hard carrier. Specific size and weight limits apply. Always confirm current requirements directly with Pegasus before booking.',
    petsAjetTitle: 'AJet',
    petsAjetBody: 'AJet accepts small pets in-cabin and larger breeds in the hold. Weight limits and carrier requirements vary by route. Always confirm directly with AJet before booking.',
    petsAirlineVerifyNote: 'Airline policies change. Always confirm pet travel rules directly with the airline before booking your flight.',
    petsSummerHeatTitle: 'Summer Heat Warning',
    petsSummerHeatBody: 'TRNC temperatures regularly exceed 35 °C from June to September. Hold travel in these months carries serious health risks. Where possible, choose in-cabin travel and fly in early morning or late evening hours.',
    petsSnubNosedTitle: 'Snub-Nosed Breeds',
    petsSnubNosedBody: 'Brachycephalic (short-muzzled) dogs and cats — including Bulldogs, Pugs, Boxers, Shih Tzus, Persian cats, and similar breeds — face embargoes or restrictions on many airlines year-round and are often banned from hold travel in summer. Check with your specific airline before booking.',
    petsReentryTitle: 'Re-Entry Rule',
    petsReentryBody: 'If you travel outside TRNC with your pet and return, the full import requirements apply again. There is no exemption for pets that are already resident in TRNC.',
