    petsRegistrationBody: 'Under TRNC law (Köpek Tanımlanması ve Kaydı Yasası), all dogs must be microchipped and registered with the local municipality. Registration must be renewed annually.',
    petsTrncLawNote: 'TRNC has its own animal welfare legislation. Turkey\'s laws (No. 5199 / 7527) do not apply in Northern Cyprus — always refer to TRNC regulations.',
    petsVaccineScheduleTitle: 'Vaccination Schedule',
    petsVaccineDogsTitle: 'Dogs — core vaccines',
    petsVaccineDogsBody: 'Distemper, Parvovirus, Hepatitis (initial course + annual booster) and Rabies (annual booster). Your vet may also recommend Leptospirosis and Kennel Cough vaccines depending on your dog\'s lifestyle.',
    petsVaccineCatsTitle: 'Cats — core vaccines',
