    essDrivingPlate1: 'TRNC plates: white background, distinct code format',
    essDrivingPlate2: 'South Cyprus (RoC) plates: typically display the EU identifier strip',
    essDrivingPlate3: 'Rental vehicles often carry identifiable plate markings in both north and south',
    essCurrPrimary: 'Turkish Lira (₺ / TRY) is the official currency in Northern Cyprus.',
    essCurrAccepted: 'EUR, GBP and USD are widely accepted at hotels, tourist restaurants, and larger shops.',
    essCurrCash: 'Cash is expected at local markets, smaller pharmacies, and most everyday services.',
    essCurrATM: 'ATMs available in major towns — Lefkoşa, Girne, and Gazimağusa.',
    essCurrBureaux: 'Exchange bureaus (döviz büfeleri) offer cash exchange; counter rates differ from official Central Bank rates.',
    essCurrRatesBtn: 'View today\'s exchange rates',
    essHolFixedTitle: 'Fixed-date national holidays',
    essHolReligiousTitle: 'Religious holidays (shift yearly)',
    essHolYearNote: '2026 dates — religious holidays follow the Islamic lunar calendar and fall ~11 days earlier each year.',
    essHolNewYear: 'New Year\'s Day — 1 Jan',
    essHolChildrenDay: 'National Sovereignty & Children\'s Day — 23 Apr',
    essHolLabourDay: 'Labour Day — 1 May',
    essHolAtaturkDay: 'Atatürk Commemoration, Youth & Sports Day — 19 May',
    essHolPeaceDay: 'Peace & Freedom Day — 20 Jul',
    essHolVictoryDay: 'Victory Day — 30 Aug',
    essHolTRDay: 'Turkish Republic Day — 29 Oct',
    essHolTRNCDay: 'TRNC Republic Day — 15 Nov',
    essHolRamazan: 'Ramazan Bayramı (Eid al-Fitr) — 3 days · approx. 29–31 Mar 2026',
    essHolKurban: 'Kurban Bayramı (Eid al-Adha) — 4 days · approx. 6–9 Jun 2026',
    essCardLiving: "Living Here",
    essLivingLastReviewed: "Last reviewed: July 2026 · seasonal — check locally",
    essLivingWaterTitle: "Tap water",
    essLivingWater1: "Locals drink bottled water, not tap. Mains water is chlorinated and fine for washing, brushing teeth and cooking, but is generally not recommended for drinking.",
    essLivingWater2: "Large refillable bottles (damacana, ~19 L) are cheap and delivered to your door — the usual choice for households.",
    essLivingHoursTitle: "Summer working hours",
    essLivingHours1: "In summer (roughly mid-June to mid-September) government and public offices move to a morning-only schedule — commonly around 07:30–14:00, with no afternoon session.",
    essLivingHours2: "Many shops take a long midday break in the summer heat and reopen in the late afternoon. Run errands in the morning.",
    essLivingHours3: "Banks and public offices close earlier than shops — go early in the day.",
    essLivingCutsTitle: "Power & water cuts",
    essLivingCuts1: "Short power and water cuts happen, especially at summer peak demand. Keep bottled water, a torch or power bank, and your phone charged.",
    essLivingCuts2: "Electricity faults (KIB-TEK): call 188. Planned cuts are posted on KIB-TEK's Facebook page, not in this app.",
    essLivingCuts3: "Water cuts are announced by your local municipality (belediye) — usually on their Facebook page.",
    essLivingCuts4: "Homes with a rooftop tank often keep water running for a while after a mains cut.",
    essLivingJellyTitle: "Jellyfish season",
    essLivingJelly1: "Jellyfish are most common in the warm months (roughly June to September), usually near the coast after warm, calm spells.",
    essLivingJelly2: "If stung, rinse with seawater (not fresh water), remove any tentacles carefully, and seek help for a severe reaction. Ask locals or lifeguards about current conditions.",
    essLivingViperTitle: "Vipers & snakes",
    essLivingViper1: "Cyprus has the venomous blunt-nosed viper (koca engerek). It is active in the warm months (spring to autumn), mostly in rural, rocky and farmland areas and around dawn and dusk.",
    essLivingViper2: "On trails wear closed shoes, watch where you step, and don't reach into rock crevices or long grass. Snakes avoid people and usually move away.",
    essLivingViper3: "If bitten, stay calm, keep the limb still and below heart level, and get to a hospital — antivenom is available. Do not cut or suck the wound.",
    essHolClosuresTitle: "What's closed",
    essHolClosuresNote: "On public holidays — and especially the multi-day Bayram periods — government offices, banks and many shops close. Pharmacies keep a duty rota and larger supermarkets often stay open. Plan ahead around Bayram.",
    essCurrCards: "Cards (Visa/Mastercard) work at supermarkets, chain stores, hotels, fuel stations and most town restaurants — but markets, village shops, taxis and small pharmacies are often cash-only.",
    essPortsAirTitle: 'Airports',
    essPortsErcan: 'Ercan International Airport (ECN) — the north\'s main airport. Flights connect via Turkey (Istanbul, Ankara, and others).',
    essPortsLarnacaNote: 'Larnaca (LCA) and Paphos (PFO) airports are in south Cyprus — reachable via a border crossing.',
    essPortsSeaTitle: 'Seaports',
    essPortsGirne: 'Girne (Kyrenia) — passenger ferry connections to Turkey (Taşucu, Mersin).',
    essPortsGazi: 'Gazimağusa (Famagusta) — main commercial port; limited passenger routes to Turkey.',
    essBordersComingSoon: 'Content pending verification — coming soon.',
    essEmbComingSoon: 'Content pending verification — coming soon.',
    essBordersLastReviewed: 'Last reviewed: June 2026 · verify before travel',
    essBordersHoursNote: 'Hours are indicative — confirm at crossing',
    essBordersOpen24h: '~24 h', essBordersLimitedHours: 'Limited hours',
    essBordersPedestrian: 'Pedestrians only', essBordersVehiclePed: 'Vehicles & pedestrians',
    essBordersLedrapalaceNote: "Cyprus's first Green Line crossing to open; inside the UN buffer zone. Pedestrians and cyclists only — cars must use Metehan (Ayios Dometios). Documents scanned, not stamped. Free. (Night hours may be reduced in the off-season.)",
    essBordersInsTitle: 'Driving south: Green Line insurance',
    essBordersIns1: 'Purchase Green Line insurance at the crossing booth before entering the south — mandatory for all vehicles.',
    essBordersIns2: 'TRNC and Turkish-backed vehicle insurance is not valid in the Republic of Cyprus.',
    essBordersIns3: 'Green Line insurance is third-party cover only.',
    essBordersDocTitle: 'Documents & entry',
    essBordersDocEU: 'EU citizens: national ID card is generally accepted. All others need a passport.',
    essBordersDocStamp: 'Ask staff at the crossing to stamp a separate entry card if you want to avoid a TRNC stamp in your passport.',
    essBordersDocRoC: 'Republic of Cyprus immigration rules apply on the southern side.',
    essBordersDocEntryRoute: 'If you entered the island via Ercan Airport or by sea into the north, the Republic of Cyprus may treat this as irregular entry and refuse you crossing to the south. Confirm your entry route is recognised before relying on a southern crossing.',
    essEmbLastReviewed: 'Last reviewed: June 2026 · verify before visiting',
    essEmbTurkeyTitle: 'Embassy of Turkey',
