    essEmbTurkeyNote: 'The only formally accredited diplomatic mission in TRNC. Turkey is the sole UN member to recognise TRNC.',
    essEmbOtherTitle: 'Other nationalities',
    essEmbOtherNote: 'These are limited-service offices (visa/information only). Full consular services for most nationalities are handled by their embassy in south Nicosia, reachable via the crossings.',
