    petsTurkiyeNote1: 'Türkiye\'den gelen evcil hayvanlar için titre testi gereksinimleri diğer ülkelerden farklı olabilir. Seyahat planlamadan önce KKTC Veteriner Dairesi ile doğrudan iletişime geçin.',
    petsTurkiyeNote2: 'Türkiye\'den gelen tüm uçuşlar Ercan Havalimanı\'na iner — varışta standart ithalat prosedürleri ve gümrük denetimi uygulanır.',
    petsOtherNote: 'Gösterilen gereksinimler asgari standart prosedürü yansıtmaktadır. Menşei ülkenize göre ek veya farklı gereksinimler söz konusu olabilir. Seyahat öncesinde menşei ülkenizi belirterek KKTC Veteriner Dairesi ile iletişime geçin.',
    petsOtherStep6Body: 'Seyahatten en fazla 10 gün önce devlet akrediteli veterinerinizden resmi ihracat sağlık sertifikası alın. Gereken format ülkeye göre değişebilir — KKTC Veteriner Dairesi ile doğrulayın.',
