    petsPegasusTitle: 'Pegasus Hava Yolları',
    petsCabinTitle: 'Kabin içi',
    petsHoldTitle: 'Ambar (kargo)',
    petsPegasusCabinBody: 'Yalnızca küçük evcil hayvanlar. Maksimum toplam ağırlık (hayvan + taşıyıcı): 8 kg. Taşıyıcı koltuk altına sığmalıdır. Yer sayısı sınırlıdır — rezervasyon sırasında havayolunu bilgilendirin.',
    petsPegasusHoldBody: 'Büyük evcil hayvanlar havayolu onaylı sert taşıyıcıda ambara alınır. Boyut ve ağırlık sınırları uygulanır. Rezervasyon öncesinde Pegasus ile güncel gereksinimleri doğrulayın.',
    petsAjetTitle: 'AJet',
    petsAjetBody: 'AJet, küçük evcil hayvanları kabinde, büyük ırkları ise ambarda kabul eder. Ağırlık sınırları ve taşıyıcı gereksinimleri rotaya göre değişir. Rezervasyon öncesinde AJet ile doğrudan iletişime geçin.',
    petsAirlineVerifyNote: 'Havayolu politikaları değişebilir. Uçuşunuzu rezerve etmeden önce evcil hayvan seyahat kurallarını doğrudan havayolu ile teyit edin.',
    petsSummerHeatTitle: 'Yaz Sıcaklığı Uyarısı',
    petsSummerHeatBody: 'KKTC\'de Haziran-Eylül arası sıcaklıklar düzenli olarak 35 °C\'nin üzerine çıkar. Bu aylarda ambar seyahati ciddi sağlık riskleri taşır. Mümkünse kabin seyahatini tercih edin ve sabahın erken saatlerinde ya da geç akşam uçuşları seçin.',
    petsSnubNosedTitle: 'Kısa Burunlu Irklar',
    petsSnubNosedBody: 'Brakisefal (kısa burunlu) köpek ve kediler — Bulldog, Pug, Boksör, Shih Tzu, İran kedisi ve benzeri ırklar — pek çok havayolunda ambar yasağına veya kısıtlamalarına tabidir; özellikle yaz aylarında. Rezervasyon öncesinde havayolunuzu mutlaka kontrol edin.',
    petsReentryTitle: 'Yeniden Giriş Kuralı',
    petsReentryBody: 'Evcil hayvanınızla KKTC dışına çıkıp döndüğünüzde ithalat gereksinimleri yeniden geçerli olur. KKTC\'de ikamet eden hayvanlar için herhangi bir muafiyet uygulanmaz.',
    petsFriendlyVenuesTitle: 'Evcil Hayvana Dost Mekanlar',
    petsFriendlyVenuesSub: 'Kuzey Kıbrıs\'ta evcil hayvana izin veren otel, restoran, plaj ve yürüyüş yollarını içeren rehber çok yakında.',
    // Slice 5 — Sahiplenme
    petsOwningTitle: 'KKTC\'de Evcil Hayvan Sahiplenmek',
    petsRegistrationTitle: 'Mikro Çip ve Kayıt',
    petsRegistrationBody: 'KKTC hukuku (Köpek Tanımlanması ve Kaydı Yasası) uyarınca tüm köpekler mikro çip takılmış ve yerel belediyeye kayıt ettirilmiş olmalıdır. Kayıt yıllık olarak yenilenmesi gerekir.',
    petsTrncLawNote: 'KKTC\'nin kendi hayvan refahı mevzuatı vardır. Türkiye\'nin hayvan koruma kanunları (No. 5199 / 7527) Kuzey Kıbrıs\'ta geçerli değildir — her zaman KKTC mevzuatına başvurun.',
    petsVaccineScheduleTitle: 'Aşı Takvimi',
    petsVaccineDogsTitle: 'Köpekler — temel aşılar',
    petsVaccineDogsBody: 'Distemper, Parvovirüs, Hepatit (başlangıç serisi + yıllık rapel) ve Kuduz (yıllık rapel). Köpeğinizin yaşam tarzına bağlı olarak veterineriniz Leptospiroz ve Öksürük aşılarını da önerebilir.',
    petsVaccineCatsTitle: 'Kediler — temel aşılar',
    petsVaccineCatsBody: 'Felin Kaliçivirus, Rinotrakeit, Panleukopeni (başlangıç serisi + yıllık rapel) ve Kuduz (yıllık rapel). Ev içinde yaşayan kediler daha sınırlı bir aşı takvimi uygulayabilir — veterinerinizle görüşün.',
    petsFindVet: 'KKTC\'de Veteriner Bul',
    petsCrueltyTitle: 'Hayvan İstismarı veya İhmalini Bildirme',
    petsCrueltyBody: 'Şüphe duyduğunuz hayvan istismarı veya ihmalini KKTC Veteriner Dairesi\'ne veya yerel belediyenize bildirin. Her ikisi de KKTC hukuku kapsamında soruşturma yapmakla yükümlüdür.',
    petsApartmentTitle: 'Apartman ve Bina Kuralları',
    petsApartmentBody: 'Apartman binalarında evcil hayvan sahiplenme kuralları, tek bir ulusal yasayla değil kira sözleşmesi ve bina yönetimi tarafından belirlenir. Evcil hayvan almadan önce kiralık sözleşmenizi inceleyin ve bina yöneticinizle görüşün.',
