    essHolFixedTitle: 'Sabit tarihli ulusal tatiller',
    essHolReligiousTitle: 'Dini tatiller (tarihler yıla göre değişir)',
    essHolYearNote: '2026 tarihleri — dini tatiller İslami takvime göre her yıl yaklaşık 11 gün erkene kayar.',
    essHolNewYear: 'Yılbaşı — 1 Ocak',
    essHolChildrenDay: 'Ulusal Egemenlik ve Çocuk Bayramı — 23 Nisan',
    essHolLabourDay: 'İşçi Bayramı — 1 Mayıs',
    essHolAtaturkDay: 'Atatürk\'ü Anma, Gençlik ve Spor Bayramı — 19 Mayıs',
    essHolPeaceDay: 'Barış ve Özgürlük Bayramı — 20 Temmuz',
    essHolVictoryDay: 'Zafer Bayramı — 30 Ağustos',
    essHolTRDay: 'Türkiye Cumhuriyet Bayramı — 29 Ekim',
    essHolTRNCDay: 'KKTC Cumhuriyet Bayramı — 15 Kasım',
    essHolRamazan: 'Ramazan Bayramı — 3 gün · yaklaşık 29–31 Mart 2026',
    essHolKurban: 'Kurban Bayramı — 4 gün · yaklaşık 6–9 Haziran 2026',
    essCardLiving: "Burada Yaşam",
    essLivingLastReviewed: "Son güncelleme: Temmuz 2026 · mevsimlik — yerel olarak teyit edin",
    essLivingWaterTitle: "Musluk suyu",
    essLivingWater1: "Yerliler musluk suyunu değil şişe suyu içer. Şebeke suyu klorludur; yıkanma, diş fırçalama ve yemek pişirme için uygundur, ancak içmek için genellikle önerilmez.",
    essLivingWater2: "Büyük damacanalar (~19 L) ucuzdur ve kapınıza kadar getirilir — evlerde en yaygın tercih budur.",
    essLivingHoursTitle: "Yaz mesai saatleri",
    essLivingHours1: "Yazın (yaklaşık haziran ortasından eylül ortasına) resmi daireler ve kamu kurumları öğleden önce mesaisine geçer — genellikle 07:30–14:00 arası, öğleden sonra mesaisi olmaz.",
    essLivingHours2: "Birçok dükkân yaz sıcağında uzun bir öğle molası verir ve ikindiden sonra tekrar açılır. İşlerinizi sabah halledin.",
    essLivingHours3: "Bankalar ve kamu kurumları dükkânlardan daha erken kapanır — güne erken başlayın.",
    essLivingCutsTitle: "Elektrik ve su kesintileri",
    essLivingCuts1: "Kısa elektrik ve su kesintileri olabilir, özellikle yaz tüketim zirvesinde. Yanınızda şişe suyu, el feneri veya powerbank bulundurun ve telefonunuzu şarjlı tutun.",
    essLivingCuts2: "Elektrik arızası (KIB-TEK): 188'i arayın. Planlı kesintiler bu uygulamada değil, KIB-TEK'in Facebook sayfasında duyurulur.",
    essLivingCuts3: "Su kesintileri bağlı olduğunuz belediye tarafından — genellikle Facebook sayfasından — duyurulur.",
    essLivingCuts4: "Çatısında depo bulunan evlerde, şebeke kesildikten sonra da musluklar bir süre akmaya devam eder.",
    essLivingJellyTitle: "Denizanası mevsimi",
    essLivingJelly1: "Denizanaları en çok sıcak aylarda (yaklaşık haziran–eylül), genellikle sıcak ve durgun havalardan sonra kıyıya yakın görülür.",
    essLivingJelly2: "Sokması hâlinde tatlı suyla değil deniz suyuyla durulayın, dokunaçları dikkatlice temizleyin; ağır tepkide yardım alın. Güncel durumu yerlilere veya cankurtaranlara sorun.",
    essLivingViperTitle: "Engerek ve yılanlar",
    essLivingViper1: "Kıbrıs'ta zehirli koca engerek yılanı bulunur. Sıcak aylarda (ilkbahardan sonbahara) etkindir; çoğunlukla kırsal, kayalık ve tarım alanlarında, şafak ve alacakaranlık saatlerinde görülür.",
    essLivingViper2: "Patikalarda kapalı ayakkabı giyin, bastığınız yere dikkat edin, kaya oyuklarına veya uzun otlara elinizi sokmayın. Yılanlar insandan kaçar ve genellikle uzaklaşır.",
    essLivingViper3: "Isırılırsanız sakin kalın, uzvu hareketsiz ve kalp seviyesinin altında tutun ve hastaneye gidin — panzehir mevcuttur. Yarayı kesmeyin veya emmeyin.",
    essHolClosuresTitle: "Neler kapalı",
    essHolClosuresNote: "Resmi tatillerde — özellikle birkaç günlük Bayram dönemlerinde — resmi daireler, bankalar ve birçok dükkân kapalıdır. Eczaneler nöbet tutar, büyük marketler genellikle açık kalır. Bayram öncesi planınızı yapın.",
    essCurrCards: "Kartlar (Visa/Mastercard) marketlerde, zincir mağazalarda, otellerde, akaryakıt istasyonlarında ve şehirdeki çoğu restoranda geçer — ancak pazarlar, köy dükkânları, taksiler ve küçük eczaneler çoğunlukla yalnızca nakit kabul eder.",
    essPortsAirTitle: 'Havalimanları',
    essPortsErcan: 'Ercan Uluslararası Havalimanı (ECN) — kuzeyinin ana havalimanı. Uçuşlar Türkiye üzerinden yapılır (İstanbul, Ankara ve diğerleri).',
    essPortsLarnacaNote: 'Larnaka (LCA) ve Baf (PFO) havalimanları güney Kıbrıs\'tadır — sınır kapısından geçerek ulaşılabilir.',
    essPortsSeaTitle: 'Deniz Limanları',
    essPortsGirne: 'Girne — Türkiye\'ye yolcu feribot seferleri (Taşucu, Mersin).',
    essPortsGazi: 'Gazimağusa — ana ticaret limanı; Türkiye\'ye sınırlı yolcu seferleri.',
    essBordersComingSoon: 'İçerik doğrulama aşamasında — yakında.',
    essEmbComingSoon: 'İçerik doğrulama aşamasında — yakında.',
    essBordersLastReviewed: 'Son güncelleme: Haziran 2026 · seyahattan önce doğrulayın',
    essBordersHoursNote: 'Saatler yaklaşık olup sınır kapısından teyit edilmelidir',
    essBordersOpen24h: '~24 saat', essBordersLimitedHours: 'Sınırlı saatler',
    essBordersPedestrian: 'Yalnızca yayalar', essBordersVehiclePed: 'Araçlar & yayalar',
    essBordersLedrapalaceNote: 'Kıbrıs\'ta ilk açılan Yeşil Hat kapısı; BM tampon bölgesi içindedir. Yalnızca yayalar ve bisikletliler — araçlar Metehan\'ı (Ayios Dometios) kullanmalıdır. Belgeler taranır, damgalanmaz. Ücretsiz. (Sezon dışında gece saatleri sınırlı olabilir.)',
    essBordersInsTitle: 'Güneye sürüş: Yeşil Hat sigortası',
    essBordersIns1: 'Güneye geçmeden önce sınır kapısı gişesinden Yeşil Hat sigortası satın alın — tüm araçlar için zorunludur.',
    essBordersIns2: 'KKTC ve Türk destekli araç sigortası Kıbrıs Cumhuriyeti\'nde geçerli değildir.',
    essBordersIns3: 'Yeşil Hat sigortası yalnızca üçüncü şahıs kapsamı sunar.',
