    essCardLiving: "الحياة هنا",
    essLivingLastReviewed: "آخر مراجعة: يوليو 2026 · موسمي — تحقّق محلياً",
    essLivingWaterTitle: "ماء الصنبور",
    essLivingWater1: "يشرب السكان المياه المعبّأة لا ماء الصنبور. ماء الشبكة مُكلْور وصالح للغسل وتنظيف الأسنان والطبخ، لكن لا يُنصح بشربه عموماً.",
    essLivingWater2: "القوارير الكبيرة القابلة لإعادة التعبئة (نحو 19 لتراً) رخيصة وتُوصَّل إلى بابك — وهي الخيار المعتاد للبيوت.",
    essLivingHoursTitle: "ساعات العمل الصيفية",
    essLivingHours1: "في الصيف (من منتصف يونيو تقريباً إلى منتصف سبتمبر) تتحوّل الدوائر الحكومية والمكاتب العامة إلى دوام صباحي فقط — عادةً نحو 07:30–14:00 دون فترة بعد الظهر.",
    essLivingHours2: "تأخذ كثير من المحلات استراحة طويلة ظهراً في حرّ الصيف وتعيد الفتح في آخر النهار. أنجز مهامك صباحاً.",
    essLivingHours3: "تُغلق البنوك والمكاتب العامة قبل المحلات — اذهب باكراً.",
    essLivingCutsTitle: "انقطاع الكهرباء والماء",
    essLivingCuts1: "قد يحدث انقطاع قصير للكهرباء والماء، خاصةً في ذروة الاستهلاك صيفاً. احتفظ بماء معبّأ ومصباح يدوي أو بطارية محمولة وأبقِ هاتفك مشحوناً.",
    essLivingCuts2: "أعطال الكهرباء (KIB-TEK): اتصل بالرقم 188. تُعلَن الانقطاعات المخطّطة على صفحة KIB-TEK في فيسبوك، لا في هذا التطبيق.",
    essLivingCuts3: "تُعلن بلديتك المحلية عن انقطاع الماء — عادةً على صفحتها في فيسبوك.",
    essLivingCuts4: "البيوت التي فيها خزان على السطح يستمر الماء فيها لبعض الوقت بعد انقطاع الشبكة.",
    essLivingJellyTitle: "موسم قناديل البحر",
    essLivingJelly1: "تكثر قناديل البحر في الأشهر الدافئة (من يونيو إلى سبتمبر تقريباً)، عادةً قرب الساحل بعد فترات دافئة وهادئة.",
    essLivingJelly2: "عند اللسع، اشطف بماء البحر لا بالماء العذب، وأزل اللوامس بحذر، واطلب المساعدة عند رد فعل شديد. اسأل السكان أو المنقذين عن الأحوال الحالية.",
    essLivingViperTitle: "الأفاعي والثعابين",
    essLivingViper1: "يوجد في قبرص أفعى سامة (الأفعى اللبنانية / koca engerek). تنشط في الأشهر الدافئة (من الربيع إلى الخريف)، غالباً في المناطق الريفية والصخرية والزراعية وعند الفجر والغسق.",
    essLivingViper2: "في المسارات ارتدِ حذاءً مغلقاً، وانتبه لموضع قدمك، ولا تُدخل يدك في شقوق الصخور أو الأعشاب الطويلة. تتجنّب الثعابين البشر وغالباً ما تبتعد.",
    essLivingViper3: "إذا لُدغت، ابقَ هادئاً، وأبقِ الطرف ثابتاً وتحت مستوى القلب، واذهب إلى المستشفى — المصل المضاد متوفّر. لا تشقّ الجرح ولا تمصّه.",
    essHolClosuresTitle: "ما هو مغلق",
