    essDrivingPlate3: 'Los vehículos de alquiler en ambos lados suelen ser identificables',
    essCurrPrimary: 'Lira turca (₺ / TRY) — moneda oficial de Chipre del Norte.',
    essCurrAccepted: 'EUR, GBP y USD se aceptan ampliamente en hoteles, restaurantes turísticos y grandes almacenes.',
    essCurrCash: 'Los mercados locales, pequeñas farmacias y muchos comercios prefieren efectivo.',
    essCurrATM: 'Hay cajeros automáticos en las principales ciudades — Nicosia, Girne, Famagusta.',
    essCurrBureaux: 'Las casas de cambio (döviz büfeleri) cambian efectivo; el tipo difiere del tipo oficial del Banco Central.',
    essCurrRatesBtn: 'Ver los tipos del día',
    essHolFixedTitle: 'Festivos fijos',
    essHolReligiousTitle: 'Fiestas religiosas (fechas variables)',
    essHolYearNote: 'Fechas para 2026 — las fiestas religiosas adelantan ~11 días cada año.',
    essHolNewYear: 'Año Nuevo — 1 ene', essHolChildrenDay: 'Día de la Soberanía Nacional y del Niño — 23 abr',
    essHolLabourDay: 'Día del Trabajo — 1 may', essHolAtaturkDay: 'Conmemoración de Atatürk, Juventud y Deporte — 19 may',
    essHolPeaceDay: 'Día de la Paz y la Libertad — 20 jul', essHolVictoryDay: 'Día de la Victoria — 30 ago',
    essHolTRDay: 'Día de la República de Turquía — 29 oct', essHolTRNCDay: 'Día de la República TRNC — 15 nov',
    essHolRamazan: 'Eid al-Fitr (Şeker Bayramı) — 3 días · aprox. 29–31 mar 2026',
    essHolKurban: 'Eid al-Adha (Kurban Bayramı) — 4 días · aprox. 6–9 jun 2026',
    essCardLiving: "Vivir aquí",
    essLivingLastReviewed: "Última revisión: julio de 2026 · estacional — confírmalo localmente",
    essLivingWaterTitle: "Agua del grifo",
    essLivingWater1: "Los residentes beben agua embotellada, no del grifo. El agua de la red está clorada y sirve para lavarse, cepillarse los dientes y cocinar, pero en general no se recomienda beberla.",
    essLivingWater2: "Los garrafones reutilizables grandes (~19 L) son baratos y se entregan a domicilio — la opción habitual en los hogares.",
    essLivingHoursTitle: "Horario de verano",
    essLivingHours1: "En verano (aproximadamente de mediados de junio a mediados de septiembre) las oficinas públicas pasan a un horario solo de mañana — normalmente sobre las 07:30–14:00, sin turno de tarde.",
    essLivingHours2: "Muchas tiendas hacen una larga pausa al mediodía por el calor y reabren a última hora de la tarde. Haz los trámites por la mañana.",
    essLivingHours3: "Los bancos y las oficinas públicas cierran antes que las tiendas — ve temprano.",
    essLivingCutsTitle: "Cortes de luz y agua",
    essLivingCuts1: "Se producen cortes breves de luz y agua, sobre todo en el pico de consumo del verano. Ten agua embotellada, una linterna o batería externa y el móvil cargado.",
    essLivingCuts2: "Averías eléctricas (KIB-TEK): llama al 188. Los cortes programados se anuncian en la página de Facebook de KIB-TEK, no en esta aplicación.",
    essLivingCuts3: "Los cortes de agua los anuncia tu municipio (belediye) — normalmente en su página de Facebook.",
    essLivingCuts4: "En las casas con depósito en el tejado, los grifos suelen seguir dando agua un rato tras un corte de la red.",
    essLivingJellyTitle: "Temporada de medusas",
    essLivingJelly1: "Las medusas son más frecuentes en los meses cálidos (aproximadamente de junio a septiembre), normalmente cerca de la costa tras periodos cálidos y tranquilos.",
    essLivingJelly2: "Si te pica, enjuaga con agua de mar (no dulce), retira los tentáculos con cuidado y busca ayuda si la reacción es grave. Pregunta a los locales o socorristas por las condiciones.",
    essLivingViperTitle: "Víboras y serpientes",
    essLivingViper1: "En Chipre hay una víbora venenosa (koca engerek). Está activa en los meses cálidos (de primavera a otoño), sobre todo en zonas rurales, rocosas y agrícolas, al amanecer y al anochecer.",
    essLivingViper2: "En los senderos usa calzado cerrado, mira dónde pisas y no metas las manos en grietas de rocas ni en hierba alta. Las serpientes evitan a las personas y suelen alejarse.",
    essLivingViper3: "Si te muerde, mantén la calma, deja la extremidad inmóvil y por debajo del corazón y acude a un hospital — hay antídoto. No cortes ni chupes la herida.",
    essHolClosuresTitle: "Qué está cerrado",
    essHolClosuresNote: "En los días festivos — y sobre todo en los periodos de varios días del Bayram — las oficinas públicas, los bancos y muchas tiendas cierran. Las farmacias mantienen guardias y los grandes supermercados suelen abrir. Planifica con antelación en torno al Bayram.",
    essCurrCards: "Las tarjetas (Visa/Mastercard) se aceptan en supermercados, cadenas, hoteles, gasolineras y la mayoría de los restaurantes de ciudad — pero mercados, tiendas de pueblo, taxis y farmacias pequeñas suelen ser solo en efectivo.",
    essPortsAirTitle: 'Aeropuertos',
    essPortsErcan: 'Aeropuerto Internacional de Ercan (ECN) — principal del norte. Vuelos vía Turquía (Estambul, Ankara, etc.).',
    essPortsLarnacaNote: 'Aeropuertos de Larnaca (LCA) y Pafos (PFO) en el sur — accesibles por los cruces fronterizos.',
    essPortsSeaTitle: 'Puertos marítimos',
    essPortsGirne: 'Kyrenia (Girne) — ferris a Turquía (Taşucu, Mersin).',
    essPortsGazi: 'Famagusta (Gazimağusa) — principal puerto comercial; tráfico de pasajeros limitado a Turquía.',
    essBordersComingSoon: 'Contenido en verificación — próximamente.', essEmbComingSoon: 'Contenido en verificación — próximamente.',
    essBordersLastReviewed: 'Última actualización: jun 2026 · comprueba antes de viajar',
    essBordersHoursNote: 'Horarios orientativos — confirma en el cruce',
    essBordersOpen24h: '~24h', essBordersLimitedHours: 'Horario limitado',
    essBordersPedestrian: 'Solo peatones', essBordersVehiclePed: 'Vehículos y peatones',
    essBordersLedrapalaceNote: 'El primer paso de la Línea Verde en abrir en Chipre; dentro de la zona tampón de la ONU. Solo peatones y ciclistas — los coches deben usar Metehan (Ayios Dometios). Documentos escaneados, sin sello. Gratuito. (El horario nocturno puede reducirse en temporada baja.)',
    essBordersInsTitle: 'Cruce al sur: seguro de la Línea Verde',
    essBordersIns1: 'Compra un seguro de Línea Verde en el cruce antes de entrar al sur — obligatorio para todos los vehículos.',
    essBordersIns2: 'El seguro de vehículos del TRNC y Turquía no es válido en la República de Chipre.',
    essBordersIns3: 'El seguro de Línea Verde cubre solo responsabilidad civil frente a terceros.',
    essBordersDocTitle: 'Documentación y entrada',
    essBordersDocEU: 'Ciudadanos UE: el DNI suele ser aceptado. Los demás necesitan pasaporte.',
    essBordersDocStamp: 'Pide que el sello se ponga en un papel aparte si no quieres el sello del TRNC en tu pasaporte.',
    essBordersDocRoC: 'En el sur se aplican las normas de inmigración de la República de Chipre.',
    essBordersDocEntryRoute: 'Si entraste a la isla por el aeropuerto de Ercan o por mar hacia el norte, la República de Chipre puede considerar esto una entrada irregular y negarte el paso al sur. Confirma que tu ruta de entrada está reconocida antes de confiar en un cruce sur.',
    essEmbLastReviewed: 'Última actualización: jun 2026 · comprueba antes de visitar',
    essEmbTurkeyTitle: 'Embajada de Turquía',
