    essEmbTurkeyEmergencyLabel: 'Emergencias (24 h)',
    essEmbFamagustaTitle: 'Consulado General de Turquía — Famagusta',
    essEmbTurkeyNote: 'Única misión diplomática oficialmente acreditada en el TRNC. Turquía es el único miembro de la ONU que reconoce el TRNC.',
    essEmbOtherTitle: 'Otras nacionalidades',
    essEmbOtherNote: 'Son oficinas de servicios limitados (solo visa/información). Los servicios consulares completos para la mayoría de las nacionalidades los gestionan sus embajadas en Nicosia sur, accesibles a través de los cruces.',
    essEmbCaveat: 'Verifica los datos de contacto antes de visitar. La lista puede cambiar.',
