    essCardLiving: "Leben vor Ort",
    essLivingLastReviewed: "Zuletzt geprüft: Juli 2026 · saisonal — vor Ort bestätigen",
    essLivingWaterTitle: "Leitungswasser",
    essLivingWater1: "Einheimische trinken Flaschenwasser, kein Leitungswasser. Das Leitungswasser ist gechlort und zum Waschen, Zähneputzen und Kochen geeignet, zum Trinken wird es jedoch generell nicht empfohlen.",
    essLivingWater2: "Große Mehrweg-Wasserballons (~19 L) sind günstig und werden ins Haus geliefert — die übliche Wahl der Haushalte.",
    essLivingHoursTitle: "Sommerarbeitszeiten",
    essLivingHours1: "Im Sommer (etwa von Mitte Juni bis Mitte September) stellen Behörden und öffentliche Ämter auf einen reinen Vormittagsdienst um — meist etwa 07:30–14:00 Uhr, ohne Nachmittagsdienst.",
    essLivingHours2: "Viele Geschäfte machen in der Sommerhitze eine lange Mittagspause und öffnen am späten Nachmittag wieder. Erledigungen morgens machen.",
    essLivingHours3: "Banken und Ämter schließen früher als Geschäfte — gehen Sie früh am Tag.",
    essLivingCutsTitle: "Strom- und Wasserausfälle",
    essLivingCuts1: "Kurze Strom- und Wasserausfälle kommen vor, besonders zur sommerlichen Spitzenlast. Halten Sie Flaschenwasser, eine Taschenlampe oder Powerbank bereit und das Handy geladen.",
    essLivingCuts2: "Stromstörungen (KIB-TEK): 188 anrufen. Geplante Abschaltungen werden auf der Facebook-Seite von KIB-TEK angekündigt, nicht in dieser App.",
    essLivingCuts3: "Wasserabschaltungen kündigt Ihre Gemeinde (belediye) an — meist auf ihrer Facebook-Seite.",
    essLivingCuts4: "In Häusern mit Dachtank läuft das Wasser nach einem Netzausfall oft noch eine Weile weiter.",
    essLivingJellyTitle: "Quallensaison",
    essLivingJelly1: "Quallen treten vor allem in den warmen Monaten auf (etwa Juni bis September), meist küstennah nach warmen, ruhigen Phasen.",
    essLivingJelly2: "Bei Kontakt mit Meerwasser (nicht Süßwasser) spülen, Tentakel vorsichtig entfernen und bei starker Reaktion Hilfe suchen. Fragen Sie Einheimische oder Rettungsschwimmer nach den Bedingungen.",
    essLivingViperTitle: "Vipern und Schlangen",
    essLivingViper1: "Auf Zypern gibt es die giftige Levanteotter (koca engerek). Sie ist in den warmen Monaten aktiv (Frühling bis Herbst), meist in ländlichen, felsigen und landwirtschaftlichen Gebieten sowie in der Dämmerung.",
    essLivingViper2: "Tragen Sie auf Wegen geschlossene Schuhe, achten Sie auf Ihren Tritt und greifen Sie nicht in Felsspalten oder hohes Gras. Schlangen meiden Menschen und ziehen sich meist zurück.",
    essLivingViper3: "Bei einem Biss ruhig bleiben, die Gliedmaße ruhig und unterhalb des Herzens halten und ins Krankenhaus fahren — ein Gegengift ist verfügbar. Die Wunde nicht einschneiden oder aussaugen.",
    essHolClosuresTitle: "Was geschlossen ist",
    essHolClosuresNote: "An Feiertagen — und besonders in den mehrtägigen Bayram-Zeiten — sind Behörden, Banken und viele Geschäfte geschlossen. Apotheken haben einen Notdienst, große Supermärkte bleiben oft offen. Planen Sie rund um Bayram im Voraus.",
    essCurrCards: "Karten (Visa/Mastercard) werden in Supermärkten, Ketten, Hotels, Tankstellen und den meisten Stadtrestaurants akzeptiert — Märkte, Dorfläden, Taxis und kleine Apotheken sind aber oft nur bar.",
    essPortsAirTitle: 'Flughäfen',
    essPortsErcan: 'Internationaler Flughafen Ercan (ECN) — Hauptflughafen des Nordens. Flüge über die Türkei (Istanbul, Ankara usw.).',
    essPortsLarnacaNote: 'Flughäfen Larnaka (LCA) und Paphos (PFO) im Süden — über Grenzübergänge erreichbar.',
    essPortsSeaTitle: 'Seehäfen',
    essPortsGirne: 'Kyrenia (Girne) — Fähren in die Türkei (Taşucu, Mersin).',
    essPortsGazi: 'Famagusta (Gazimağusa) — Haupthandelshafen; begrenzter Passagierverkehr in die Türkei.',
    essBordersComingSoon: 'Inhalt wird geprüft — bald verfügbar.', essEmbComingSoon: 'Inhalt wird geprüft — bald verfügbar.',
    essBordersLastReviewed: 'Zuletzt aktualisiert: Juni 2026 · vor Reiseantritt prüfen',
    essBordersHoursNote: 'Öffnungszeiten sind Richtwerte — am Übergang bestätigen',
    essBordersOpen24h: '~24h', essBordersLimitedHours: 'Eingeschränkte Öffnungszeiten',
    essBordersPedestrian: 'Nur Fußgänger', essBordersVehiclePed: 'Fahrzeuge & Fußgänger',
    essBordersLedrapalaceNote: 'Erster geöffneter Grenzübergang der Grünen Linie auf Zypern; innerhalb der UN-Pufferzone. Nur Fußgänger und Radfahrer — Autos müssen Metehan (Ayios Dometios) nutzen. Dokumente werden gescannt, nicht gestempelt. Kostenlos. (Nachtstunden können außerhalb der Saison eingeschränkt sein.)',
    essBordersInsTitle: 'Einreise in den Süden: Grüne-Linie-Versicherung',
    essBordersIns1: 'Schließen Sie am Übergang eine Grüne-Linie-Versicherung ab, bevor Sie in den Süden einreisen — für alle Fahrzeuge Pflicht.',
    essBordersIns2: 'Die Kfz-Versicherung des TRNC und der Türkei gilt in der Republik Zypern nicht.',
    essBordersIns3: 'Die Grüne-Linie-Versicherung deckt nur die Haftpflicht gegenüber Dritten.',
    essBordersDocTitle: 'Dokumente & Einreise',
    essBordersDocEU: 'EU-Bürger: Personalausweis wird in der Regel akzeptiert. Alle anderen benötigen einen Reisepass.',
    essBordersDocStamp: 'Bitten Sie darum, den Stempel auf einem separaten Blatt anzubringen, wenn kein TRNC-Stempel im Reisepass gewünscht.',
    essBordersDocRoC: 'Im Süden gelten die Einwanderungsregeln der Republik Zypern.',
    essBordersDocEntryRoute: 'Wenn Sie die Insel über den Flughafen Ercan oder auf dem Seeweg in den Norden eingereist sind, kann die Republik Zypern dies als irreguläre Einreise werten und Ihnen die Überquerung in den Süden verweigern. Vergewissern Sie sich, dass Ihre Einreiseroute anerkannt ist, bevor Sie sich auf einen südlichen Grenzübergang verlassen.',
    essEmbLastReviewed: 'Zuletzt aktualisiert: Juni 2026 · vor dem Besuch prüfen',
