    essEmbOtherNote: 'Dies sind Büros mit eingeschränkten Diensten (nur Visum/Information). Vollständige Konsulardienstleistungen für die meisten Staatsangehörigen werden von ihren Botschaften in Süd-Nikosia erbracht, die über die Grenzübergänge erreichbar sind.',
