    essCardLiving: "زندگی در اینجا",
    essLivingLastReviewed: "آخرین بازبینی: ژوئیهٔ ۲۰۲۶ · فصلی — محلی بررسی کنید",
    essLivingWaterTitle: "آب لوله‌کشی",
    essLivingWater1: "مردم محلی آب بطری می‌نوشند نه آب شیر. آب شبکه کلرزده است و برای شست‌وشو، مسواک‌زدن و پخت‌وپز مناسب است، اما نوشیدن آن معمولاً توصیه نمی‌شود.",
    essLivingWater2: "بطری‌های بزرگ قابل‌شارژ (حدود ۱۹ لیتر) ارزان‌اند و درِ خانه تحویل داده می‌شوند — انتخاب معمول خانوارها.",
    essLivingHoursTitle: "ساعات کاری تابستان",
    essLivingHours1: "در تابستان (تقریباً از اواسط ژوئن تا اواسط سپتامبر) ادارات دولتی و عمومی به شیفت فقط صبح می‌روند — معمولاً حدود ۰۷:۳۰ تا ۱۴:۰۰ و بدون شیفت بعدازظهر.",
    essLivingHours2: "بسیاری از مغازه‌ها در گرمای تابستان استراحت طولانی ظهر دارند و اواخر بعدازظهر دوباره باز می‌کنند. کارهایتان را صبح انجام دهید.",
    essLivingHours3: "بانک‌ها و ادارات عمومی زودتر از مغازه‌ها می‌بندند — صبح زود بروید.",
    essLivingCutsTitle: "قطعی برق و آب",
    essLivingCuts1: "قطعی‌های کوتاه برق و آب پیش می‌آید، به‌ویژه در اوج مصرف تابستان. آب بطری، چراغ‌قوه یا پاوربانک همراه داشته باشید و گوشی را شارژ نگه دارید.",
    essLivingCuts2: "خرابی برق (KIB-TEK): با ۱۸۸ تماس بگیرید. قطعی‌های برنامه‌ریزی‌شده در صفحهٔ فیس‌بوک KIB-TEK اعلام می‌شود، نه در این برنامه.",
    essLivingCuts3: "قطعی آب را شهرداری محلی شما (belediye) اعلام می‌کند — معمولاً در صفحهٔ فیس‌بوک آن.",
    essLivingCuts4: "در خانه‌هایی که مخزن روی پشت‌بام دارند، شیرها معمولاً تا مدتی پس از قطع شبکه همچنان آب می‌دهند.",
    essLivingJellyTitle: "فصل عروس دریایی",
    essLivingJelly1: "عروس‌های دریایی بیشتر در ماه‌های گرم (تقریباً ژوئن تا سپتامبر) دیده می‌شوند، معمولاً نزدیک ساحل پس از دوره‌های گرم و آرام.",
    essLivingJelly2: "اگر نیش زد، با آب دریا (نه آب شیرین) بشویید، شاخک‌ها را با احتیاط جدا کنید و در واکنش شدید کمک بگیرید. دربارهٔ شرایط روز از مردم محلی یا نجات‌غریق بپرسید.",
    essLivingViperTitle: "افعی و مار",
    essLivingViper1: "در قبرس افعی سمی (koca engerek) وجود دارد. در ماه‌های گرم (بهار تا پاییز) فعال است، بیشتر در مناطق روستایی، سنگلاخی و کشاورزی و در سپیده‌دم و غروب.",
    essLivingViper2: "در مسیرها کفش بسته بپوشید، مراقب جای پا باشید و دست در شکاف سنگ‌ها یا علف بلند نکنید. مارها از انسان دوری می‌کنند و معمولاً دور می‌شوند.",
    essLivingViper3: "اگر گزیده شدید، آرام بمانید، اندام را بی‌حرکت و پایین‌تر از سطح قلب نگه دارید و به بیمارستان بروید — پادزهر موجود است. زخم را نبُرید و نمکید.",
    essHolClosuresTitle: "چه چیزهایی تعطیل است",
    essHolClosuresNote: "در تعطیلات رسمی — به‌ویژه دوره‌های چندروزهٔ بایرام (عید) — ادارات دولتی، بانک‌ها و بسیاری از مغازه‌ها بسته‌اند. داروخانه‌ها به‌صورت کشیک باز هستند و فروشگاه‌های بزرگ اغلب باز می‌مانند. برای ایام بایرام از پیش برنامه‌ریزی کنید.",
    essCurrCards: "کارت‌ها (ویزا/مسترکارت) در سوپرمارکت‌ها، فروشگاه‌های زنجیره‌ای، هتل‌ها، پمپ‌بنزین‌ها و بیشتر رستوران‌های شهری پذیرفته می‌شوند — اما بازارها، مغازه‌های روستایی، تاکسی‌ها و داروخانه‌های کوچک اغلب فقط نقدی‌اند.",
    essPortsAirTitle: 'فرودگاه‌ها',
    essPortsErcan: 'فرودگاه بین‌المللی اِرجان (ECN) — فرودگاه اصلی شمال. پروازها از طریق ترکیه (استانبول، آنکارا و غیره).',
    essPortsLarnacaNote: 'فرودگاه‌های لارناکا (LCA) و پافوس (PFO) در جنوب — از طریق گذرگاه‌های مرزی قابل دسترس.',
    essPortsSeaTitle: 'بنادر دریایی',
