    essBordersLedrapalaceNote: 'اولین گذرگاه خط سبز قبرس که باز شد؛ داخل منطقه بافر سازمان ملل. فقط پیاده و دوچرخه‌سوار — اتومبیل‌ها باید از گذرگاه متهان (آیوس دومتیوس) استفاده کنند. اسناد اسکن می‌شوند، نه مُهر. رایگان. (ساعات شبانه ممکن است در خارج از فصل کاهش یابد.)',
    essBordersInsTitle: 'ورود به جنوب: بیمه خط سبز',
    essBordersIns1: 'قبل از ورود به جنوب، بیمه خط سبز را در گذرگاه تهیه کنید — برای همه خودروها اجباری است.',
    essBordersIns2: 'بیمه خودرو TRNC و ترکیه در جمهوری قبرس معتبر نیست.',
    essBordersIns3: 'بیمه خط سبز فقط مسئولیت مدنی در برابر اشخاص ثالث را پوشش می‌دهد.',
    essBordersDocTitle: 'مدارک و ورود',
    essBordersDocEU: 'شهروندان اتحادیه اروپا: کارت ملی معمولاً پذیرفته می‌شود. سایرین به گذرنامه نیاز دارند.',
    essBordersDocStamp: 'اگر نمی‌خواهید مهر TRNC در گذرنامه‌تان باشد، بخواهید روی کاغذ جداگانه مهر بزنند.',
    essBordersDocRoC: 'در جنوب قوانین مهاجرتی جمهوری قبرس اعمال می‌شود.',
    essBordersDocEntryRoute: 'اگر از طریق فرودگاه اِرجان یا از راه دریا به شمال وارد جزیره شده‌اید، جمهوری قبرس ممکن است این را ورود غیرقانونی تلقی کند و از عبور شما به جنوب امتناع کند. قبل از تکیه بر یک گذرگاه جنوبی، مطمئن شوید مسیر ورود شما به رسمیت شناخته شده است.',
